#!/usr/bin/env python3
# Apply Wanderfall v0.18.7B2 storage-grid and interaction-label polish.
from pathlib import Path
import hashlib, sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else "game")

def apply_line_patch(rel, expected_sha, ops):
    path = root / rel
    raw = path.read_bytes()
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected_sha:
        raise SystemExit(f"B2 base mismatch for {rel}: {actual} != {expected_sha}")
    text = raw.decode("utf-8")
    source_lines = text.splitlines(keepends=True)
    for start, end, replacement in sorted(ops, key=lambda item: item[0], reverse=True):
        source_lines[start:end] = replacement.splitlines(keepends=True)
    path.write_text("".join(source_lines), encoding="utf-8")

